from __future__ import annotations

import logging
import os
import pathlib
from collections.abc import Generator
from contextlib import contextmanager
from typing import Optional
from unittest.mock import MagicMock

import taf.transport.ssh as ssh  # type: ignore[import-untyped]
from paramiko import AutoAddPolicy, RSAKey, SFTPClient, SSHClient, ssh_exception


def makedir_on_remote_host(sftp: SFTPClient, remote_directory: str) -> None:
    if remote_directory in ("/", ""):
        return
    try:
        sftp.chdir(remote_directory)
    except OSError:
        remote_dir = pathlib.Path(remote_directory)
        dirname, basename = remote_dir.parent, remote_dir.stem
        makedir_on_remote_host(sftp, dirname.as_posix())
        sftp.mkdir(basename)


@contextmanager
def get_sftp_connection(
    logger: logging.Logger,
    host: str,
    port: int = 22,
    user: str = "ute",
    passwd: str = "ute",
) -> Generator[SFTPClient, None, None]:
    with _get_ssh_connection(logger, host, port, user, passwd) as transport:
        try:
            if _transport := transport.get_transport():
                sftp = SFTPClient.from_transport(_transport)
                assert sftp is not None, f"SSH connection failed. {user}@{host}:{port}, pass: {passwd}"
                yield sftp
            else:
                raise Exception(f"Cannot get transport for {user}@{host}:{port}, pass: {passwd}")
        except Exception as e:
            logger.debug(e)
        finally:
            if sftp is not None:
                sftp.close()


@contextmanager
def _get_ssh_connection(
    logger: logging.Logger, host: str, port: int = 22, user: str = "ute", passwd: str = "ute"
) -> Generator[SSHClient, None, None]:
    ssh = SSHClient()
    ssh.set_missing_host_key_policy(AutoAddPolicy())
    rsa_pkey = RSAKey.from_private_key_file(os.path.expanduser("~/.ssh/id_rsa"))
    try:
        ssh.connect(
            hostname=host,
            port=port,
            username=user,
            password=passwd,
            pkey=rsa_pkey,
            timeout=10,
        )
        yield ssh
    except (ssh_exception.NoValidConnectionsError, ssh_exception.SSHException) as err:
        logger.debug(
            "SSH connection failed, please check IP and/or TL config " "(robotlte/config/<site>/<tl_name>/__init__.py). Error: {}".format(err)
        )
        raise
    except Exception as e:
        logger.debug(f"Exception: {e}")
    finally:
        ssh.close()
        del ssh


@contextmanager
def get_ssh(
    host: str,
    username: str,
    password: str,
    timeout: float = 30.0,
    *,
    proxy: Optional[ssh.SSHConnection] = None,
    logger: logging.Logger | MagicMock = MagicMock(),
) -> Generator[ssh.SSHConnection | ssh.ProxySSHConnection, None, None]:
    connection = None
    try:
        logger.debug(f"SETUP START: 'SSH': [{host}, {username}, {password}, {timeout}]")
        if proxy is not None:
            logger.debug(f"Connecting via proxy: {proxy}")
            connection = ssh.connect(host, username, password, timeout=timeout, proxy=proxy)
        else:
            connection = ssh.connect(host, username, password, timeout=timeout)
        logger.debug(f"SETUP DONE: 'SSH': [{host}, {username}, {password}, {timeout}]")
        yield connection
    finally:
        try:
            if connection is None:
                logger.debug(f"TEARDOWN NOT NEEDED: 'SSH': [{host}, {username}, {password}, {timeout}]")
            else:
                logger.debug(f"TEARDOWN START: 'SSH': [{host}, {username}, {password}, {timeout}]")
                connection.disconnect()
                logger.debug(f"TEARDOWN DONE: 'SSH': [{host}, {username}, {password},  {timeout}]")
        except Exception as err:
            logger.warning(err)
